-- The HELI-GRIP code key (Code keys -> Parting -> HELI-GRIP), from the ISCAR
-- e-catalog's HELI-GRIP families (GRIP / GRIPA / HGPL inserts, HELIR/L,
-- HELIIR/L, HGFH tools); kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.heligrip', $ck${"title": "HELI-GRIP code key – inserts and tools", "subtitle": "Utility and ground double-ended inserts (GRIP, GRIPA, HGPL) for external, internal and face machining, and HELI tools", "example": "GRIP 3002Y", "decoder": "heli-grip", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "GRIP", "rows": [{"code": "GRIP", "meaning": "Utility double-ended inserts for external, internal and face machining"}, {"code": "GRIPA", "meaning": "Ground double-ended inserts for external, internal and face machining"}, {"code": "HGPL", "meaning": "Utility double-ended inserts for face machining"}]}, {"key": "i-width", "title": "Insert – cutting width and corner radius", "sample": "3002", "rows": [{"code": "####", "meaning": "Width and corner radius x10 (e.g. 3002 = 3.0 mm, R0.2; 3015 = 3.0 mm, R1.5 full radius)"}, {"code": "###-###", "meaning": "Width and corner radius x100 (e.g. 318-040 = 3.18 mm, R0.40)"}, {"code": "#", "meaning": "GRIPA: cutting width in mm (e.g. 3.00)"}]}, {"key": "i-radius", "title": "Insert – corner radius (GRIPA)", "rows": [{"code": "#", "meaning": "Corner radius in mm (e.g. 0.40; half the width = full radius)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "Y", "rows": [{"code": "Y", "meaning": "Utility chipformer for external, internal and face machining"}, {"code": "T", "meaning": "T variant (GRIP-T family) (inferred)"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "HELI", "meaning": "External holders for turning, grooving and parting (HELIR / HELIL; C# CAMFIX shanks)"}, {"code": "HELII", "meaning": "Grooving and turning bars with coolant holes (HELIIR / HELIIL)"}, {"code": "HGFH", "meaning": "Parting and grooving blades for 3 mm GRIP inserts"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}, {"code": "R/L", "meaning": "Right- or left-hand"}, {"code": "N", "meaning": "Neutral"}, {"code": "RE", "meaning": "Right-hand, E type (RE/LE adapters) (inferred)"}, {"code": "LE", "meaning": "Left-hand, E type (RE/LE adapters) (inferred)"}, {"code": "R/LE", "meaning": "Right- or left-hand, E type (inferred)"}]}, {"key": "t-angle", "title": "Tool – angle a° (multi-spindle blades)", "rows": [{"code": "#", "meaning": "Angle a° (0 or 5)"}]}, {"key": "t-height", "title": "Tool – blade height / shank", "rows": [{"code": "##", "meaning": "Blade height or shank size in mm (e.g. 26, 32)"}, {"code": "###", "meaning": "Blade height in mm (e.g. 100, 150)"}, {"code": "####", "meaning": "Shank height x width in mm (e.g. 2525 = 25 x 25)"}]}, {"key": "t-width", "title": "Tool – insert width (seat)", "rows": [{"code": "#", "meaning": "Insert width in mm (the seat's insert, e.g. 3)"}]}, {"key": "t-dia", "title": "Tool – D size", "rows": [{"code": "D##", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D24, D52) (inferred)"}, {"code": "D###", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D120) (inferred)"}]}, {"key": "t-pockets", "title": "Tool – pockets", "rows": [{"code": "#Z", "meaning": "Number of pockets (e.g. 2Z, 4Z)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "JHP", "meaning": "Channels for high-pressure coolant"}, {"code": "MC", "meaning": "Bottom inlets for the high-pressure coolant"}, {"code": "K", "meaning": "With coolant holes (10 bar min.; cooling tube SGCU 341 ordered separately)"}, {"code": "C", "meaning": "With coolant – frontal coolant holes (JETCUT) / internal coolant"}, {"code": "XL", "meaning": "Extra long"}, {"code": "SH", "meaning": "Short head (CNC and Swiss automatics)"}, {"code": "S", "meaning": "Single-sided blade (e.g. TGFH-S) / for next to high shoulders (e.g. PCHRS)"}, {"code": "IQ", "meaning": "IQ line (e.g. TGTR/L-IQ, PCHR/L-D-IQ)"}, {"code": "TR", "meaning": "For TRAUB and Index machines"}, {"code": "MB", "meaning": "For other manufacturers' blocks"}, {"code": "B", "meaning": "B type, e.g. DGTR/L-B-D (reinforced) / DGAD-B-D (screw-clamped) (inferred)"}, {"code": "L###", "meaning": "Tool length in mm (e.g. L120)"}, {"code": "T##", "meaning": "Maximum cutting depth in mm (e.g. T12, T20, T25) (inferred)"}, {"code": "C#", "meaning": "CAMFIX polygon shank (C4 = 40, C5 = 50, C6 = 63 mm)"}]}, {"key": "t-depth", "title": "Tool – max. grooving depth (bars)", "rows": [{"code": "##", "meaning": "Bars: the digits after the insert width (e.g. 410 = 4 mm inserts, 10 mm) (inferred)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
